use engine_native::{Engine,GameCommand,GameAction,CommandOutcome,ChoiceOption,Phase,ChoiceView,MachineSnapshot};
use engine_native::archive::{encode_archive,decode_archive};
use engine_native::ai::{BoundedPlanner,redact_opponent_hands};
use engine_native::view::{SeatPolicy,PolicyInput};
fn submit(e:&mut Engine,actor:u8,action:GameAction)->CommandOutcome {let d=e.save().last_dedup+1;e.submit(GameCommand{actor,action,expected_revision:e.revision(),dedup_id:d})}
fn answer(e:&mut Engine,s:Vec<ChoiceOption>)->CommandOutcome {let c=e.open_choice().unwrap().clone();submit(e,c.observer,GameAction::Answer{choice_id:c.id,selection:s})}
fn setup(seed:u64,n:u8)->Engine {let mut e=Engine::new(seed,n as usize);for _ in 0..12 {if e.turn().phase==Phase::Play {break}let p=e.turn().current;assert!(!matches!(submit(&mut e,p,GameAction::NextPhase),CommandOutcome::Rejected(_)));}for p in 0..n{e.debug_clear_hand(p)}e}
fn play(e:&mut Engine,c:u32,t:u8)->CommandOutcome {submit(e,0,GameAction::PlayCard{card:c,targets:vec![t]})}
struct Passive;impl SeatPolicy for Passive{fn act(&mut self,_:&PolicyInput)->Option<GameAction>{None}}
fn ownership(){
 let e=Engine::new(443,4);let mut s=e.save();let mid=s.core.players[0].hand.pop().unwrap();assert!(Engine::restore(&s).is_err());println!("FIXED_MIDDLE_MISSING: removed Card({mid}) rejected");
 let mut s=e.save();let last=e.catalog().cards.len() as u32-1;for p in &mut s.core.players{p.hand.retain(|c|*c!=last);p.equips.retain(|c|*c!=last);p.judge.retain(|c|*c!=last)}s.core.deck.retain(|c|*c!=last);s.core.discard.retain(|c|*c!=last);s.core.table.retain(|c|*c!=last);assert!(Engine::restore(&s).is_ok());println!("OPEN_TRAILING_MISSING: highest Card({last}) removed from all zones; restore accepted");
 for p in &mut s.core.players{p.hand.clear();p.equips.clear();p.judge.clear()}s.core.deck.clear();s.core.discard.clear();s.core.table.clear();assert!(Engine::restore(&s).is_ok());println!("OPEN_EMPTY_OWNERSHIP: all physical cards removed; restore accepted");
}
fn liuli(){let mut e=setup(2004,3);e.debug_grant(1,"流离");e.debug_place(1,"tao");let sha=e.debug_place(0,"sha");play(&mut e,sha,1);assert_eq!(e.open_choice().unwrap().spec.prompt,"liuli_transfer");let mut mem=Engine::restore(&e.save()).unwrap();let decoded=decode_archive(&encode_archive(&e.save())).unwrap();let byte_err=Engine::restore(&decoded).err().expect("liuli decoded choice kind mismatch");println!("OPEN_LIULI_ARCHIVE: decoded own archive cannot restore: {byte_err:?}; choice kind {:?} -> {:?}",e.open_choice().unwrap().spec.kind,decoded.resolution.open_choice.as_ref().unwrap().spec.kind);let offset=e.log().len();answer(&mut e,vec![ChoiceOption::Player(2)]);answer(&mut mem,vec![ChoiceOption::Player(2)]);assert_eq!(e.debug_hp(2),3);assert_eq!(e.state_hash(),mem.state_hash());assert_eq!(&e.log()[offset..],mem.log());println!("FIXED_LIULI: transfer answer direct/memory hp2=3, full hashes and event suffix equal");}
fn hujia(){
 let mut e=setup(2201,3);e.debug_grant(1,"护驾");let shan=e.debug_place(0,"shan");let sha=e.debug_place(0,"sha");play(&mut e,sha,1);assert_eq!(e.open_choice().unwrap().observer,0);assert_eq!(e.open_choice().unwrap().spec.prompt,"hujia_respond");assert!(matches!(e.ai_session(1).choice(),Some(ChoiceView::Other{..})));assert!(e.debug_hand(0).contains(&shan));let err=Engine::restore(&e.save()).err().expect("hujia restore currently fails");println!("OPEN_HUJIA_RESTORE: valid holder confirmation snapshot rejected: {err:?}");answer(&mut e,vec![ChoiceOption::Confirm]);assert!(!e.debug_hand(0).contains(&shan));println!("FIXED_HUJIA_OWNER: private card id not offered to defender; holder must confirm");
 let mut e=setup(2202,4);e.debug_grant(1,"护驾");e.debug_place(2,"shan");e.debug_place(3,"shan");let sha=e.debug_place(0,"sha");play(&mut e,sha,1);assert_eq!(e.open_choice().unwrap().observer,2);answer(&mut e,vec![ChoiceOption::Pass]);assert_eq!(e.debug_hp(1),3);assert!(e.open_choice().is_none());println!("OPEN_HUJIA_QUEUE: first holder 2 passes; holder 3 never asked, defender takes damage");
 let mut e=setup(2203,3);e.debug_grant(0,"无双");e.debug_grant(1,"护驾");e.debug_place(2,"shan");let sha=e.debug_place(0,"sha");play(&mut e,sha,1);answer(&mut e,vec![ChoiceOption::Confirm]);assert_eq!(e.debug_hp(1),4);assert!(e.open_choice().is_none());println!("OPEN_HUJIA_WUSHUANG: single helper Shan ends Wushuang attack requiring two dodges");
}
fn ai(){
 let mut e=Engine::new(2301,3);assert!(!matches!(e.submit(GameCommand{actor:0,expected_revision:e.revision(),dedup_id:1_000_000,action:GameAction::NextPhase}),CommandOutcome::Rejected(_)));let mut e=Engine::restore(&e.save()).unwrap();let a=e.run_policy(0,&mut Passive);let p=e.plan_action(0,&BoundedPlanner::new(64));let b=e.apply_plan(&p).unwrap();assert!(matches!(a,CommandOutcome::Rejected(engine_native::RejectReason::DuplicateCommand)));assert!(matches!(b,CommandOutcome::Rejected(engine_native::RejectReason::DuplicateCommand)));println!("STILL_AI_DEDUP: run_policy={a:?}, apply_plan={b:?} after dedup=1000000 and restore");
 let mut e=setup(2302,3);e.debug_place(0,"sha");e.debug_place(1,"shan");e.debug_place(2,"sha");let mut s=e.save();s.core.discard.append(&mut s.core.deck);let a=Engine::restore(&s).unwrap();s.core.players[1].hand.swap(0,0);let c=s.core.players[1].hand[0];s.core.players[1].hand[0]=s.core.players[2].hand[0];s.core.players[2].hand[0]=c;let b=Engine::restore(&s).unwrap();assert_eq!(a.ai_session(0).view(),b.ai_session(0).view());assert_eq!(a.ai_session(0).events(),b.ai_session(0).events());let pa=a.plan_action(0,&BoundedPlanner::new(64));let pb=b.plan_action(0,&BoundedPlanner::new(64));assert_ne!(format!("{:?}",pa.action),format!("{:?}",pb.action));println!("OPEN_AI_EMPTY_DECK: equal visible states, hidden Shan swap changes plan {:?} -> {:?}",pa.action,pb.action);
 let mut e=Engine::new(2304,3);redact_opponent_hands(&mut e,0);let err=Engine::restore(&e.save()).err().expect("sampling duplicates physical cards");println!("OPEN_AI_SAMPLED_OWNERSHIP: sampled hands copy deck IDs without removal; restore={err:?}");
 let mut e=setup(2303,3);let shan=e.debug_place(1,"shan");let sha=e.debug_place(0,"sha");play(&mut e,sha,1);let p=e.plan_action(1,&BoundedPlanner::new(64));assert_eq!(p.nodes_used,2);assert!(matches!(p.action,GameAction::Answer{ref selection,..} if selection==&vec![ChoiceOption::Pass]));let mut back=Engine::restore(&e.save()).unwrap();answer(&mut back,vec![ChoiceOption::Card(shan)]);assert_eq!(back.debug_hp(1),4);println!("STILL_AI_CANDIDATES: [Pass, Shan], max=1; nodes=2 (Pass and NextPhase), legal Shan omitted");
}
fn archives(){
 for (name,prompt,response) in [("duel","duel_sha","sha"),("savage","aoe_response","sha"),("snatch","nullify_window","nullify")] {
  let mut e=setup(2401,3);e.debug_place(1,response);let c=e.debug_place(0,name);let out=submit(&mut e,0,GameAction::PlayCard{card:c,targets:if name=="savage"{vec![]}else{vec![1]}});assert!(!matches!(out,CommandOutcome::Rejected(_)),"{out:?}");let s=e.save();let actual=e.open_choice().expect("known choice").spec.prompt;assert_eq!(actual,prompt);assert!(Engine::restore(&s).is_ok());let err=decode_archive(&encode_archive(&s)).unwrap_err();println!("OPEN_ARCHIVE_VALID_PROMPT: generated {actual:?} memory restore works; own encoded archive rejected {err:?}");
 }
 let mut e=setup(2402,3);e.debug_place(1,"shan");let c=e.debug_place(0,"sha");play(&mut e,c,1);let mut s=e.save();s.resolution.open_choice.as_mut().unwrap().spec.prompt="review_unknown_prompt";assert!(decode_archive(&encode_archive(&s)).is_err());println!("FIXED_UNKNOWN_PROMPT: unknown prompt rejected, fixed registry replaces unbounded pool");
 // New holder field is not validated even when no hujia response is pending.
 let mut s=e.save();let mut changed=false;for park in &mut s.resolution.parks{if let MachineSnapshot::Sha{hujia_holder,..}=&mut park.machine{*hujia_holder=Some(254);changed=true;}}assert!(changed);assert!(Engine::restore(&s).is_ok());println!("OPEN_HUJIA_HOLDER_BOUNDS: hujia_holder=254 accepted in a 3-player snapshot");
}
fn gender(){let mut e=setup(2501,4);let mut s=e.save();for (p,g) in [(1,2),(2,9),(3,5)]{s.core.players[p].general_slots=[Some(g),None];}e=Engine::restore(&s).unwrap();e.debug_grant(0,"离间");let card=e.debug_place(0,"tao");let skill=e.catalog().skill_by_name("离间").unwrap();submit(&mut e,0,GameAction::ActivateSkill{skill});answer(&mut e,vec![ChoiceOption::Card(card)]);let c=e.open_choice().unwrap().clone();assert_eq!(c.spec.prompt,"lijian_targets");assert!(!c.spec.options.contains(&ChoiceOption::Player(2)));let err=Engine::restore(&e.save()).err().expect("gender filtered choice mismatch");println!("OPEN_GENDER_RESTORE: male-only targets {:?}; restoring legitimate choice rejected {err:?}",c.spec.options);}
fn wiring(){let e=Engine::new(1,3);let gs=engine_native::content::standard::STANDARD_GENERALS;for (name,skill) in [("曹操","护驾"),("貂蝉","离间"),("大乔","流离"),("周瑜","反间"),("孙尚香","结姻"),("华佗","急救")]{assert!(gs.iter().find(|g|g.0==name).unwrap().2.contains(&skill));assert!(e.catalog().skill_by_name(skill).is_some());}println!("FIXED_GENERAL_WIRING: six skill arrays now contain registered skills; end-to-end gameplay coverage separate");}
fn main(){ownership();liuli();hujia();ai();archives();gender();wiring();println!("REVIEW14_PROBES_COMPLETE ruleset={}",Engine::new(1,3).save().ruleset_version);}
